/**
 * Agency procurement forecasts (/forecasts/<slug>) that pass the thin gate, deduplicated.
 * Generated by getForecastSitemapEntries (src/lib/seo/forecast-pages.ts); listed in the sitemap
 * index via SITEMAP_CHILDREN.
 */
import { renderUrlset, sitemapResponse, sitemapFailure, SITEMAP_URL_LIMIT } from '@/lib/seo/sitemap-xml';
import { getForecastSitemapEntries } from '@/lib/seo/forecast-pages';
import { SITE_URL } from '@/lib/seo/sitemap-sections';

// Rendered per request, cached at the CDN (s-maxage 6h + 1 day stale-while-revalidate), so a
// read failure answers 503 instead of being frozen into a build artifact.
export const dynamic = 'force-dynamic';

export async function GET() {
  try {
    const rows = await getForecastSitemapEntries();
    if (rows.length > SITEMAP_URL_LIMIT) {
      // Never silently truncate: past this point the family needs a second child file.
      throw new Error(`forecast sitemap has ${rows.length} URLs, over the ${SITEMAP_URL_LIMIT} per-file limit`);
    }
    return sitemapResponse(
      renderUrlset(rows.map((r) => ({ url: `${SITE_URL}/forecasts/${r.slug}`, changeFrequency: 'weekly', priority: 0.5 }))),
    );
  } catch (err) {
    return sitemapFailure('forecasts', err);
  }
}
